import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const group = new Group();
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // ──────────────────────────────────────────────────────────────────────────
  // CREATE PLANE WITH BRUSHED-METAL TEXTURE
  // ──────────────────────────────────────────────────────────────────────────

  const geometry = new PlaneGeometry(1.4, 0.9, 1, 1);
  const material = new MeshBasicNodeMaterial();

  // Load brushed-metal map
  let metalTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        metalTexture = tex;
        metalTexture.needsUpdate = true;
        material.colorNode = uniform(metalTexture);
        material.needsUpdate = true;
      });
  }

  const plane = new Mesh(geometry, material);
  group.add(plane);

  // ──────────────────────────────────────────────────────────────────────────
  // RENDER TEXT LABEL: "Journal 1"
  // ──────────────────────────────────────────────────────────────────────────

  const textLabel = ctx.fontAtlas.createText('Journal 1', {
    fontSize: 39,
    color: '#16161d',
    align: 'center',
    letterSpacingPx: 0,
  });

  textLabel.position.set(0, 0, 0.1);
  group.add(textLabel);

  // ──────────────────────────────────────────────────────────────────────────
  // CLEANUP & HANDLERS
  // ──────────────────────────────────────────────────────────────────────────

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (metalTexture) {
      metalTexture.dispose();
    }
  };

  group.userData.handlers = {};

  return group;
}
